import { Asset } from 'expo-asset';
import { ImageManipulator, SaveFormat } from 'expo-image-manipulator';
import * as jpeg from 'jpeg-js';
import type { TfliteModel } from 'react-native-fast-tflite';
import modelLabelsJson from './modelLabels.json';

// Google AIY "food_V1" classifier (MobileNet V1, Apache-2.0): 192×192 RGB uint8 in,
// 2024 uint8-quantized softmax scores out. modelLabels.json is generated by
// data/food-db/build_nutrition.py and maps each output index to [model label, dish id | null].
const INPUT_SIZE = 192;
const OUTPUT_SCALE = 1 / 256;
const MODEL_LABELS = modelLabelsJson as [label: string, dishId: string | null][];
const BACKGROUND_INDEX = 0;

export interface FoodSuggestion {
  label: string; // the model's own label, e.g. "Butter chicken"
  dishId: string | null; // our food database id, when the label maps to one
  confidence: number; // 0–1
}

export interface Recognition {
  suggestions: FoodSuggestion[]; // best first, at most 4
}

let modelPromise: Promise<TfliteModel | null> | null = null;

// The TFLite native module only exists in development/production builds. In Expo Go
// recognition quietly reports itself unavailable and logging stays fully manual.
const loadModel = () => {
  if (!modelPromise) {
    modelPromise = (async () => {
      try {
        const { loadTensorflowModel } = require('react-native-fast-tflite') as typeof import('react-native-fast-tflite');
        // Resolve the bundled model to a file:// path first. Release builds pack it as an
        // Android raw resource, which fast-tflite can't open from require() directly.
        const [modelAsset] = await Asset.loadAsync(require('../../../assets/models/food_v1.tflite'));
        if (!modelAsset.localUri) {
          throw new Error('Food model asset could not be resolved to a local file');
        }
        return await loadTensorflowModel({ url: modelAsset.localUri }, []);
      } catch (error) {
        console.info('Food recognition unavailable:', error instanceof Error ? error.message : error);
        return null;
      }
    })();
  }
  return modelPromise;
};

// Start loading the (20 MB) model early, e.g. when the camera opens.
export const warmUpRecognizer = () => {
  loadModel();
};

// Center-crops the photo to a square, scales it to the model's input size and
// returns the raw RGB bytes.
const toModelInput = async (photoUri: string): Promise<Uint8Array> => {
  const original = await ImageManipulator.manipulate(photoUri).renderAsync();
  const side = Math.min(original.width, original.height);

  const scaled = await ImageManipulator.manipulate(photoUri)
    .crop({
      originX: (original.width - side) / 2,
      originY: (original.height - side) / 2,
      width: side,
      height: side,
    })
    .resize({ width: INPUT_SIZE, height: INPUT_SIZE })
    .renderAsync();
  const { base64 } = await scaled.saveAsync({ base64: true, format: SaveFormat.JPEG, compress: 1 });
  if (!base64) {
    throw new Error('Image manipulator returned no image data');
  }

  const jpegBytes = Uint8Array.from(atob(base64), (char) => char.charCodeAt(0));
  const { data } = jpeg.decode(jpegBytes, { useTArray: true, formatAsRGBA: false });
  return data;
};

// Collapses the model's scores into dish suggestions. Several model labels can map
// to one dish, so their confidences are summed; unmapped labels are kept by name.
const toSuggestions = (scores: Uint8Array): FoodSuggestion[] => {
  const ranked = Array.from(scores, (score, index) => ({ index, confidence: score * OUTPUT_SCALE }))
    .filter(({ index }) => index !== BACKGROUND_INDEX)
    .sort((a, b) => b.confidence - a.confidence)
    .slice(0, 10);

  const byKey = new Map<string, FoodSuggestion>();
  for (const { index, confidence } of ranked) {
    if (confidence < 0.03) break;
    const [label, dishId] = MODEL_LABELS[index];
    const key = dishId ?? `label:${label}`;
    const existing = byKey.get(key);
    if (existing) {
      existing.confidence += confidence;
    } else {
      byKey.set(key, { label, dishId, confidence });
    }
  }

  return [...byKey.values()].sort((a, b) => b.confidence - a.confidence).slice(0, 4);
};

// Returns null when recognition isn't available (Expo Go) or fails.
export const recognizeFood = async (photoUri: string): Promise<Recognition | null> => {
  const model = await loadModel();
  if (!model) {
    return null;
  }

  try {
    const input = await toModelInput(photoUri);
    // The model wants exactly the input bytes, not a larger backing buffer
    const buffer =
      input.byteOffset === 0 && input.byteLength === input.buffer.byteLength ? input.buffer : input.slice().buffer;
    const [output] = await model.run([buffer as ArrayBuffer]);
    return { suggestions: toSuggestions(new Uint8Array(output)) };
  } catch (error) {
    console.warn('Food recognition failed', error);
    return null;
  }
};
